import sys
from heapq import heappop, heappush

def dijkstra(n, edges, start, x, y):
    graph = [[] for _ in range(n + 1)]
    for u, v in edges:
        graph[u].append((v, y))
        graph[v].append((u, y))

    for u, v in edges:
        if u < v:
            graph[u].append((v, x))
        else:
            graph[v].append((u, x))

    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        current_dist, u = heappop(pq)
        if current_dist > dist[u]:
            continue
        for v, weight in graph[u]:
            distance = current_dist + weight
            if distance < dist[v]:
                dist[v] = distance
                heappush(pq, (distance, v))

    return min(dist[1:])

